<?php
namespace App\Http\Controllers;
use App\Product; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class CommunityController extends Controller {
 public function review(Request $request,$id){Product::where('publication_status',1)->findOrFail($id);$this->validate($request,['customer_name'=>'required|max:120','email'=>'nullable|email|max:150','rating'=>'required|integer|min:1|max:5','review'=>'required|min:10|max:2000']);DB::table('product_reviews')->insert(['product_id'=>$id,'user_id'=>auth()->id(),'customer_name'=>$request->customer_name,'email'=>$request->email,'rating'=>$request->rating,'review'=>$request->review,'is_approved'=>0,'created_at'=>now(),'updated_at'=>now()]);return redirect()->back()->with('success','Thank you. Your review will appear after moderation.');}
 public function question(Request $request,$id){Product::where('publication_status',1)->findOrFail($id);$this->validate($request,['customer_name'=>'required|max:120','email'=>'nullable|email|max:150','question'=>'required|min:5|max:2000']);DB::table('product_questions')->insert(['product_id'=>$id,'user_id'=>auth()->id(),'customer_name'=>$request->customer_name,'email'=>$request->email,'question'=>$request->question,'is_approved'=>0,'created_at'=>now(),'updated_at'=>now()]);return redirect()->back()->with('success','Your question was submitted. Our team will answer it shortly.');}
 public function support(Request $request){$this->validate($request,['customer_name'=>'required|max:120','email'=>'required|email|max:150','phone'=>'nullable|max:30','subject'=>'required|max:180','message'=>'required|min:10|max:3000']);DB::table('support_requests')->insert(['user_id'=>auth()->id(),'customer_name'=>$request->customer_name,'email'=>$request->email,'phone'=>$request->phone,'subject'=>$request->subject,'order_number'=>$request->order_number,'message'=>$request->message,'status'=>'new','created_at'=>now(),'updated_at'=>now()]);return redirect()->back()->with('success','Your support request has been received.');}
}
